contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept parameters to test sending and withdrawing
    // amountToSend: amount of wei to send into c (must be provided by caller of run)
    // withdrawAmount: amount to attempt to withdraw via withdraw
    function run(uint amountToSend, uint withdrawAmount) public payable {
        require(address(this).balance >= amountToSend, "not enough balance to fund send");

        // Read initial observable state
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Send Ether to c to trigger fallback (must be a top-level call)
        // Use call to address(c).call{value: amountToSend}("");
        (bool sent, ) = address(c).call{value: amountToSend}("");
        require(sent, "send to c failed");

        // After sending, depositsCount should have incremented by 1
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // Now withdraw withdrawAmount from c using withdraw (InvMutTest is owner so this should succeed)
        // Capture whether withdraw reverted
        bool withdrewReverted;
        try c.withdraw(withdrawAmount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        uint finalBalance = address(c).balance;

        // General property asserted:
        // 1) Sending plain Ether increments depositsCount by exactly 1 and increases c.balance by amountToSend.
        // 2) Since InvMutTest is the owner of c, withdraw should NOT revert and finalBalance should equal afterBalance - withdrawAmount,
        //    except when withdrawAmount > afterBalance in which case the call will revert; so the assert encodes both cases.
        assert(
            // deposit observed correctly
            afterDeposits == beforeDeposits + 1
            && afterBalance == beforeBalance + amountToSend
            // withdraw behavior: if it reverted then withdrawAmount > afterBalance (insufficient balance to transfer),
            // else finalBalance decreased by exactly withdrawAmount
            && (
                (withdrewReverted && withdrawAmount > afterBalance)
                || (!withdrewReverted && finalBalance + withdrawAmount == afterBalance)
            )
        );
    }

    // Allow receiving refunds from c when it transfers to this contract
    receive() external payable {}
}

