contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will test that withdraw/withdrawAll/sendMoney only succeed when called by the owner (which is the address that deployed C).
    // The InvMutTest contract is NOT the owner of c (the checker deploys c and then deploys this test with c passed in),
    // so calls made from this contract should revert for owner-only functions. To also exercise successful owner behavior,
    // we accept parameters that simulate calls from the owner by providing the expected resulting balances and counts
    // observed through c's public surface (this is how the general rule can be stated for all inputs).

    // Single public test function driven by parameters.
    // - op: 0 = withdrawAll, 1 = withdraw(amount), 2 = sendMoney(target,value,data)
    // - amount: amount to withdraw/send (when applicable)
    // - valueForCall: Ether to send to c before attempting the operation (so c has balance to withdraw)
    // - target: address to be used for sendMoney
    // - dataLen: length of calldata for sendMoney (we won't use its contents meaningfully)
    function run(uint8 op, uint256 amount, uint256 valueForCall, address payable target, uint256 dataLen) public payable {
        require(op <= 2);
        // Ensure this contract has enough balance to pre-fund c when sending Ether to it.
        if (valueForCall > 0) {
            require(address(this).balance >= valueForCall);
            // fund c by triggering its fallback payable function
            // Fallback increments depositsCount and accepts Ether
            // This is a top-level state-changing call on c
            c.f{value: valueForCall}();
        }

        // read observable state before the operation
        uint256 beforeBalance = address(c).balance;
        uint256 beforeDeposits = c.depositsCount();

        bool reverted = false;
        // Perform the chosen operation. Each state-changing call must be a top-level statement.
        if (op == 0) {
            // withdrawAll
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else if (op == 1) {
            try c.withdraw(amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else { // op == 2
            // prepare dummy data for call length dataLen
            bytes memory data = new bytes(dataLen);
            try c.sendMoney(target, amount, data) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // read observable state after the operation
        uint256 afterBalance = address(c).balance;
        uint256 afterDeposits = c.depositsCount();

        // General rule asserted:
        // - depositsCount only changes when we sent Ether into c via fallback (i.e., valueForCall>0 causes increment by 1 per call).
        // - If the call reverted, c.balance must be unchanged.
        // - If the call did not revert, c.balance cannot have increased as a result of withdraw/withdrawAll/sendMoney.
        //   (owner-only functions transfer Ether out of c or do nothing; they never increase c.balance).
        assert(
            // depositsCount increased iff we funded c above (funding uses fallback once)
            (afterDeposits == beforeDeposits + (valueForCall > 0 ? 1 : 0))
            // If reverted, balance unchanged
            && (reverted ? afterBalance == beforeBalance : true)
            // If not reverted, balance is <= beforeBalance (cannot increase)
            && (!reverted ? afterBalance <= beforeBalance : true)
        );
    }

    // Accept Ether so that this contract can fund c in the test
    receive() external payable {}
}

