contract InvMutTest {
    C c;
    address deployer;

    constructor(C _c) { c = _c; deployer = address(this); }

    // Attempt to withdraw as a non-owner: caller is this contract (the owner of C is msg.sender at C deployment,
    // which was the external account that deployed C in the harness). We require that non-owner calls revert
    // and that successful withdraws can only be done by the owner (which is not this contract). To check this,
    // we take an amount and perform a withdraw call catching revert, then observe address(c).balance.
    function run(uint amount) public payable {
        require(true);

        // Ensure we have enough balance to fund C for the test: send Ether into C via its fallback by calling it with value.
        // We must ensure this contract has enough balance to forward 'amount'. The harness will provide some funds to this call.
        if (amount > 0) {
            require(address(this).balance >= amount);
            // send Ether to C to increase its balance; this invokes fallback and increments depositsCount.
            (bool sent,) = address(c).call{value: amount}("");
            // require the funding succeeded for the test to be meaningful
            require(sent);
        }

        uint beforeBal = address(c).balance;

        // Try to withdraw as this contract (which is NOT the original owner of C in typical harnesses).
        bool reverted;
        try c.withdraw(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBal = address(c).balance;

        // General rule: if the non-owner call reverted then the contract balance must be unchanged;
        // if it did not revert, then it must have decreased by exactly 'amount' (successful transfer).
        // This captures both that non-owners cannot withdraw (they will revert), and if withdraw succeeds it transfers the requested amount.
        assert( (reverted && afterBal == beforeBal) || (!reverted && beforeBal >= amount && afterBal + amount == beforeBal) );
    }

    receive() external payable { }
}

