    function run(address payable maybeOwner, uint withdrawAmount) public payable {
        require(true);
        // Ensure this test contract has enough Ether to fund the contract if needed
        if (msg.value > 0) {
            // nothing else needed; msg.value is provided by the caller when invoking run
        }

        // Fund c with some Ether if msg.value > 0 by calling its fallback via a direct call on c
        // This must be a top-level state-changing call on c: use the payable fallback by calling c with value
        // We cannot call address(c).call per constraints, so fund by calling c.sendMoney with owner privileges is not possible here.
        // Instead, rely on msg.value being forwarded to c by using payable(address(c)).call is disallowed; so we instead assume fresh c may have 0 balance.

        // Read before balance
        uint beforeBal = address(c).balance();

        // Attempt withdraw as non-owner: since InvMutTest deployed C, this contract is the owner; we need to simulate non-owner by calling withdraw via a try/catch on c from a different msg.sender — not possible here.
        // Instead, use the provided maybeOwner parameter to check behavior via observing that only owner (the deployer) equals c.owner().
        address contractOwner = c.owner();

        // If maybeOwner equals the recorded owner, then calling withdraw from this contract (which is the deployer) should succeed; otherwise this contract is not the owner and withdraw should revert.
        // But msg.sender for calls on c is this contract; therefore, withdraw will succeed iff c.owner() == address(this).
        // We assert the general rule: if c.owner() == address(this) then withdraw(withdrawAmount) either succeeds and decreases balance by withdrawAmount (clamped by balance), else it reverts and balance unchanged.

        bool ownerIsThis = (contractOwner == address(this));

        bool reverted;
        // perform the state-changing call on c: withdraw(withdrawAmount) as this contract
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBal = address(c).balance();

        // If this contract is the owner then withdraw must not revert and balance must decrease by exactly withdrawAmount (unless withdraw transfers more than available and thus reverts — but withdraw uses transfer and will revert if insufficient funds, so successful call means beforeBal >= withdrawAmount and afterBal == beforeBal - withdrawAmount).
        // If not owner then withdraw must revert and balance unchanged.
        assert( (ownerIsThis && !reverted && beforeBal >= withdrawAmount && afterBal == beforeBal - withdrawAmount) || (!ownerIsThis && reverted && afterBal == beforeBal) );
    }

    receive() external payable { }
}

